      return `<label class="rix-output-control rix-output-control-input" data-rix-control-kind="input" data-rix-control-input-mode="${escapeHtml2(value.inputMode || "expression")}" data-rix-control-id="${escapeHtml2(value.id)}" data-rix-control-target="${escapeHtml2(value.targetId)}"${controlStyleAttributes(value)}${controlStateAttributes(value)}${dependencies}><span class="rix-output-control-label">${escapeHtml2(value.label)}</span><span class="rix-output-control-input-row"><input type="text" value="${escapeHtml2(inputValue)}" placeholder="${escapeHtml2(value.placeholder)}" data-rix-control-input aria-label="${escapeHtml2(value.label)}"${controlInputAttributes(value, { text: true })}><button type="button" data-rix-control-commit${controlInputAttributes(value)}>Set</button></span><output data-rix-control-value>${text4(controlField(value, "value"))}</output>${controlMessages(value)}</label>`;
