    "{$": { precedence: 0, type: "brace_sigil" },
    "{^": { precedence: 0, type: "brace_sigil" },
    "{>": { precedence: 0, type: "brace_sigil" },
    "{~": { precedence: 0, type: "brace_sigil" },
    "{&": { precedence: 0, type: "brace_sigil" },
    "&": { precedence: 0, type: "separator" },
    "{!": { precedence: 0, type: "brace_sigil" },
